package fr.noxodev.noxoclaim.commands;
import fr.noxodev.noxoclaim.NoxoClaim; import org.bukkit.command.*; import java.util.*;
public final class ClaimAdminCommand implements CommandExecutor {private final NoxoClaim p;public ClaimAdminCommand(NoxoClaim p){this.p=p;}public boolean onCommand(CommandSender s,Command c,String l,String[] a){if(!s.hasPermission("noxoclaim.admin")){p.messages().send(s,"no-permission");return true;}if(a.length==0){s.sendMessage("§b/claimadmin list | delete <uuid> | deleteall <uuid> | reload | save");return true;}switch(a[0].toLowerCase()){case "list"->p.claims().all().forEach(x->s.sendMessage("§7"+x.getId()+" §fowner="+x.getOwner()+" size="+x.size()));case "delete","remove"->{if(a.length<2)return true;try{var x=p.claims().get(UUID.fromString(a[1]));if(x!=null)p.claims().remove(x);}catch(Exception ignored){}}case "deleteall"->{if(a.length<2)return true;try{UUID u=UUID.fromString(a[1]);p.claims().owned(u).forEach(p.claims()::remove);}catch(Exception ignored){}}case "save"->p.claims().save();case "reload"->{p.reloadConfig();s.sendMessage("§aConfiguration rechargée.");}}return true;}}
